#!/usr/bin/env python3
"""Supplement triggered by measured native repeat noise; same bundled binary."""
import json, os, random, re, subprocess, time
from pathlib import Path
import repeat_probe as probe

ROOT=Path(__file__).resolve().parent
MODEL='qwen3.8:27b'
CASES={'K01','K06','U06'}

def run():
    out=ROOT/'qwen_cache_control';out.mkdir(exist_ok=True)
    prompts=json.loads((ROOT/'results/qwen3.8_27b/rendered_prompts.json').read_text())
    prompts=[r for r in prompts if r['case_id'] in CASES]
    assert len(prompts)==12
    # No sampled answer is generated by this empty-prompt model-load request.
    load=probe.call('/api/generate',{'model':MODEL,'prompt':'','keep_alive':'15m','options':{**probe.pilot.OPTIONS,'num_predict':1}})
    process_lines=subprocess.check_output(['ps','-eo','args'],text=True).splitlines()
    lines=[l for l in process_lines if l.startswith('/usr/lib/ollama/llama-server ') and '--model ' in l]
    assert len(lines)==1,lines
    port=int(re.search(r'--port (\d+)',lines[0]).group(1))
    host=f'http://127.0.0.1:{port}'
    props=probe.pilot.request(host,'/props')
    (out/'runtime.json').write_text(json.dumps({'model':MODEL,'process':lines[0],'props':props,'load_response':load,
        'cases':sorted(CASES),'repeats':10,'calls':240,'start_time':time.time(),
        'qualification':'Supplementary direct /completion API using exact Ollama-bundled binary and rendered prompts; cache_prompt is the controlled request factor.'},indent=2))
    rng=random.Random(20261123)
    for repeat in range(10):
        block=[(p,mode) for p in prompts for mode in ('warm','cold')]
        rng.shuffle(block)
        for p,mode in block:
            req={'prompt':p['response']['_debug_info']['rendered_template'],'n_predict':1,'n_probs':20,
                'temperature':0,'seed':42,'top_k':0,'top_p':1,'min_p':0,'repeat_penalty':1,
                'presence_penalty':0,'frequency_penalty':0,'n_keep':4,
                'stream':False,'post_sampling_probs':False,'cache_prompt':mode=='warm',
                'return_tokens':True,'timings_per_token':True}
            rec={'case_id':p['case_id'],'rotation':p['rotation'],'repeat':repeat,'mode':mode,
                'request':req,'request_sha256':probe.digest(req),'started_at':time.time()}
            started=time.monotonic()
            try:
                response=probe.pilot.request(host,'/completion',req)
                rec['response']=response
                normalized={'message':{'content':response.get('content','')},'logprobs':response.get('completion_probabilities',[])}
                rec['measurement']=probe.measure(normalized,probe.MAPS[p['rotation']])
                assert rec['measurement']['valid'],rec['measurement']
            except Exception as e:
                rec['error']=repr(e)
                with (out/'responses.jsonl').open('a') as f:f.write(json.dumps(rec,ensure_ascii=False)+'\n')
                raise
            rec['elapsed_seconds']=time.monotonic()-started
            with (out/'responses.jsonl').open('a') as f:
                f.write(json.dumps(rec,ensure_ascii=False)+'\n');f.flush();os.fsync(f.fileno())
        print('CACHE_BLOCK_DONE',repeat+1,'of 10',flush=True)
    probe.call('/api/generate',{'model':MODEL,'keep_alive':0})
    (out/'COMPLETE.json').write_text(json.dumps({'calls':240,'end_time':time.time()}))
    print('CACHE_CONTROL_COMPLETE',flush=True)

if __name__=='__main__':run()
